window.NYX_APPS = {"admin": "<!doctype html>\n<html lang=\"zh-CN\" data-theme=\"dark\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>NyxBot 数据管理</title>\n  <style>\n/* ============================================================================\n   NyxBot 数据管理中心 — 样式\n   暗色 / 亮色 双主题\n   ============================================================================ */\n\n/* ── CSS 变量（暗色主题，默认）── */\n:root,\n[data-theme=\"dark\"] {\n  --bg-primary: #242424;\n  --bg-secondary: #1e1e1e;\n  --bg-tertiary: #2d2d2d;\n  --bg-hover: #363636;\n  --bg-active: #1f6feb33;\n  --border: #3a3a3a;\n  --border-light: #555;\n  --text-primary: #e6edf3;\n  --text-secondary: #9ea7b3;\n  --text-muted: #6e7681;\n  --accent: #58a6ff;\n  --accent-hover: #79c0ff;\n  --accent-dim: #1f6feb;\n  --danger: #f85149;\n  --danger-hover: #ff6b63;\n  --success: #3fb950;\n  --warning: #d29922;\n  --radius: 6px;\n  --radius-lg: 8px;\n  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);\n  --transition: 150ms ease;\n}\n\n/* ── CSS 变量（亮色主题）── */\n[data-theme=\"light\"] {\n  --bg-primary: #f9fafc;\n  --bg-secondary: #ffffff;\n  --bg-tertiary: #f0f2f5;\n  --bg-hover: #e8eaed;\n  --bg-active: #1f6feb1a;\n  --border: #d5d7db;\n  --border-light: #a0a4ab;\n  --text-primary: #1a1a2e;\n  --text-secondary: #5a5f6b;\n  --text-muted: #8b9099;\n  --accent: #1f6feb;\n  --accent-hover: #1558c2;\n  --accent-dim: #1f6feb;\n  --danger: #cf222e;\n  --danger-hover: #a40e26;\n  --success: #1a7f37;\n  --warning: #9a6700;\n  --shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n}\n\n/* ── 全局重置 ── */\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  height: 100%;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  font-size: 14px;\n  color: var(--text-primary);\n  background: var(--bg-primary);\n  overflow: hidden;\n}\n\n/* ── 整体布局 ── */\nbody {\n  display: flex;\n}\n\n/* ============================================================================\n   侧边栏\n   ============================================================================ */\n#sidebar {\n  width: 260px;\n  min-width: 260px;\n  height: 100vh;\n  background: var(--bg-secondary);\n  border-right: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.sidebar-header {\n  padding: 20px 16px 12px;\n  border-bottom: 1px solid var(--border);\n}\n\n.sidebar-header h2 {\n  font-size: 18px;\n  font-weight: 700;\n  color: var(--text-primary);\n  letter-spacing: -0.3px;\n}\n\n.sidebar-subtitle {\n  font-size: 12px;\n  color: var(--text-muted);\n  margin-top: 4px;\n}\n\n.sidebar-search {\n  padding: 10px 12px;\n}\n\n.sidebar-search input {\n  width: 100%;\n  padding: 6px 10px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  background: var(--bg-primary);\n  color: var(--text-primary);\n  font-size: 13px;\n  outline: none;\n  transition: border-color var(--transition);\n}\n\n.sidebar-search input:focus {\n  border-color: var(--accent-dim);\n}\n\n.sidebar-search input::placeholder {\n  color: var(--text-muted);\n}\n\n#model-list {\n  flex: 1;\n  overflow-y: auto;\n  padding: 4px 8px;\n}\n\n.loading-message {\n  padding: 16px;\n  color: var(--text-muted);\n  text-align: center;\n  font-size: 13px;\n}\n\n/* 模型列表项 */\n.model-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 12px;\n  border-radius: var(--radius);\n  cursor: pointer;\n  transition: background var(--transition);\n  font-size: 13px;\n  color: var(--text-secondary);\n  user-select: none;\n}\n\n.model-item:hover {\n  background: var(--bg-hover);\n  color: var(--text-primary);\n}\n\n.model-item.active {\n  background: var(--bg-active);\n  color: var(--accent);\n  font-weight: 600;\n}\n\n.model-item .model-name {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.model-item .model-sync-badge {\n  font-size: 11px;\n  color: var(--success);\n  margin-left: 6px;\n}\n\n.model-item .model-count {\n  font-size: 11px;\n  color: var(--text-muted);\n  margin-left: 8px;\n  flex-shrink: 0;\n}\n\n/* 分类标签 */\n.model-category {\n  padding: 8px 12px 4px;\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n  color: var(--text-muted);\n}\n\n/* ============================================================================\n   主内容区\n   ============================================================================ */\n#main-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  height: 100vh;\n  overflow: hidden;\n}\n\n/* 顶部工具栏 */\n#toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 20px;\n  border-bottom: 1px solid var(--border);\n  background: var(--bg-secondary);\n  gap: 16px;\n  flex-shrink: 0;\n}\n\n.toolbar-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n}\n\n.toolbar-left h1 {\n  font-size: 16px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.record-count {\n  font-size: 12px;\n  color: var(--text-muted);\n  white-space: nowrap;\n}\n\n.toolbar-right {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n/* 按钮 */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 6px 14px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all var(--transition);\n  white-space: nowrap;\n  background: var(--bg-tertiary);\n  color: var(--text-primary);\n}\n\n.btn:hover {\n  background: var(--bg-hover);\n}\n\n.btn:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n.btn-primary {\n  background: var(--accent-dim);\n  border-color: var(--accent-dim);\n  color: #fff;\n}\n\n.btn-primary:hover:not(:disabled) {\n  background: var(--accent);\n  border-color: var(--accent);\n}\n\n.btn-danger {\n  background: var(--danger);\n  border-color: var(--danger);\n  color: #fff;\n}\n\n.btn-danger:hover:not(:disabled) {\n  background: var(--danger-hover);\n  border-color: var(--danger-hover);\n}\n\n.btn-secondary:hover:not(:disabled) {\n  border-color: var(--border-light);\n}\n\n.btn-page {\n  padding: 5px 12px;\n  font-size: 12px;\n}\n\n.btn-close {\n  background: none;\n  border: none;\n  color: var(--text-muted);\n  font-size: 18px;\n  cursor: pointer;\n  padding: 4px 8px;\n  border-radius: var(--radius);\n  transition: all var(--transition);\n  line-height: 1;\n}\n\n.btn-close:hover {\n  color: var(--text-primary);\n  background: var(--bg-hover);\n}\n\n/* ============================================================================\n   表格容器\n   ============================================================================ */\n#table-container {\n  flex: 1;\n  overflow: auto;\n  padding: 0;\n}\n\n.placeholder-message {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  height: 100%;\n  color: var(--text-muted);\n  font-size: 15px;\n}\n\n.table-wrapper {\n  min-width: 100%;\n}\n\n/* 数据表格 */\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 13px;\n}\n\nthead {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n}\n\nthead th {\n  background: var(--bg-tertiary);\n  padding: 10px 14px;\n  text-align: left;\n  font-weight: 600;\n  color: var(--text-secondary);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.3px;\n  border-bottom: 2px solid var(--border);\n  white-space: nowrap;\n}\n\ntbody td {\n  padding: 8px 14px;\n  border-bottom: 1px solid var(--border);\n  color: var(--text-primary);\n  max-width: 300px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\ntbody tr:hover {\n  background: var(--bg-hover);\n}\n\n/* 操作列 */\ntd.actions {\n  white-space: nowrap;\n}\n\ntd.actions button {\n  padding: 3px 8px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  font-size: 11px;\n  cursor: pointer;\n  transition: all var(--transition);\n  background: var(--bg-tertiary);\n  color: var(--text-secondary);\n  margin-right: 4px;\n}\n\ntd.actions button:hover {\n  color: var(--text-primary);\n  border-color: var(--border-light);\n}\n\ntd.actions .btn-edit:hover {\n  color: var(--accent);\n  border-color: var(--accent-dim);\n}\n\ntd.actions .btn-delete:hover {\n  color: var(--danger);\n  border-color: var(--danger);\n}\n\n/* 空值样式 */\ntd.null-value {\n  color: var(--text-muted);\n  font-style: italic;\n}\n\n/* ============================================================================\n   分页\n   ============================================================================ */\n#pagination {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  padding: 10px 20px;\n  border-top: 1px solid var(--border);\n  background: var(--bg-secondary);\n  flex-shrink: 0;\n}\n\n#page-info {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  font-size: 13px;\n  color: var(--text-secondary);\n}\n\n#page-info .btn-page {\n  min-width: 32px;\n  text-align: center;\n}\n\n#page-info .btn-page.active {\n  background: var(--accent-dim);\n  border-color: var(--accent-dim);\n  color: #fff;\n  font-weight: 600;\n  pointer-events: none;\n}\n\n.page-ellipsis {\n  padding: 0 4px;\n  color: var(--text-muted);\n  user-select: none;\n}\n\n/* ============================================================================\n   模态框\n   ============================================================================ */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.6);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 100;\n}\n\n.modal {\n  background: var(--bg-secondary);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow);\n  width: 600px;\n  max-width: 90vw;\n  max-height: 80vh;\n  display: flex;\n  flex-direction: column;\n}\n\n.modal-sm {\n  width: 420px;\n}\n\n.modal-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 16px 20px;\n  border-bottom: 1px solid var(--border);\n}\n\n.modal-header h2 {\n  font-size: 16px;\n  font-weight: 600;\n}\n\n.modal-body {\n  padding: 20px;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.modal-footer {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 12px 20px;\n  border-top: 1px solid var(--border);\n}\n\n.confirm-detail {\n  margin-top: 8px;\n  padding: 8px 12px;\n  background: var(--bg-tertiary);\n  border-radius: var(--radius);\n  font-family: monospace;\n  font-size: 12px;\n  color: var(--text-secondary);\n  word-break: break-all;\n}\n\n/* 表单字段 */\n.form-group {\n  margin-bottom: 14px;\n}\n\n.form-group label {\n  display: block;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--text-secondary);\n  margin-bottom: 4px;\n  text-transform: uppercase;\n  letter-spacing: 0.3px;\n}\n\n.form-group input,\n.form-group textarea {\n  width: 100%;\n  padding: 8px 12px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  background: var(--bg-primary);\n  color: var(--text-primary);\n  font-size: 13px;\n  font-family: inherit;\n  outline: none;\n  transition: border-color var(--transition);\n}\n\n.form-group input:focus,\n.form-group textarea:focus {\n  border-color: var(--accent-dim);\n}\n\n.form-group input::placeholder,\n.form-group textarea::placeholder {\n  color: var(--text-muted);\n  font-size: 12px;\n  font-style: italic;\n}\n\n.form-group textarea {\n  resize: vertical;\n  min-height: 60px;\n}\n\n.form-group input[readonly] {\n  background: var(--bg-tertiary);\n  color: var(--text-muted);\n  cursor: not-allowed;\n}\n\n/* ============================================================================\n   Toast 通知\n   ============================================================================ */\n.toast {\n  position: fixed;\n  bottom: 24px;\n  left: 50%;\n  transform: translateX(-50%);\n  padding: 10px 24px;\n  border-radius: var(--radius);\n  font-size: 13px;\n  font-weight: 500;\n  z-index: 200;\n  box-shadow: var(--shadow);\n  animation: toast-in 200ms ease;\n}\n\n.toast-success {\n  background: #1a3a1a;\n  color: var(--success);\n  border: 1px solid var(--success);\n}\n\n.toast-error {\n  background: #3a1a1a;\n  color: var(--danger);\n  border: 1px solid var(--danger);\n}\n\n.toast-info {\n  background: #1a2a3a;\n  color: var(--accent);\n  border: 1px solid var(--accent-dim);\n}\n\n@keyframes toast-in {\n  from {\n    opacity: 0;\n    transform: translateX(-50%) translateY(10px);\n  }\n  to {\n    opacity: 1;\n    transform: translateX(-50%) translateY(0);\n  }\n}\n\n/* ============================================================================\n   加载动画\n   ============================================================================ */\n.loading-spinner {\n  display: inline-block;\n  width: 16px;\n  height: 16px;\n  border: 2px solid var(--border);\n  border-top-color: var(--accent);\n  border-radius: 50%;\n  animation: spin 600ms linear infinite;\n  margin-right: 8px;\n}\n\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n/* ============================================================================\n   滚动条样式\n   ============================================================================ */\n::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n::-webkit-scrollbar-thumb {\n  background: var(--border);\n  border-radius: 4px;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background: var(--border-light);\n}\n\n/* ============================================================================\n   同步状态按钮动画\n   ============================================================================ */\n#sync-btn.syncing {\n  pointer-events: none;\n  opacity: 0.7;\n}\n\n#sync-btn.syncing::before {\n  content: \"\";\n  display: inline-block;\n  width: 12px;\n  height: 12px;\n  border: 2px solid var(--border);\n  border-top-color: var(--accent);\n  border-radius: 50%;\n  animation: spin 600ms linear infinite;\n  margin-right: 4px;\n}\n\n</style>\n</head>\n<body>\n  <!-- 侧边栏：模型列表 -->\n  <aside id=\"sidebar\">\n    <div class=\"sidebar-header\">\n      <h2>📊 NyxBot</h2>\n      <p class=\"sidebar-subtitle\">数据管理中心</p>\n    </div>\n    <div class=\"sidebar-search\">\n      <input\n        type=\"text\"\n        id=\"model-filter\"\n        placeholder=\"过滤模型...\"\n        autocomplete=\"off\"\n      />\n    </div>\n    <nav id=\"model-list\">\n      <div class=\"loading-message\">加载模型列表中...</div>\n    </nav>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main id=\"main-content\">\n    <!-- 顶部工具栏 -->\n    <header id=\"toolbar\">\n      <div class=\"toolbar-left\">\n        <h1 id=\"current-model-title\">选择一个模型</h1>\n        <span id=\"record-count\" class=\"record-count\"></span>\n      </div>\n      <div class=\"toolbar-right\">\n        <button id=\"sync-btn\" class=\"btn btn-secondary\" disabled title=\"从数据源同步\">\n          🔄 同步\n        </button>\n        <button id=\"create-btn\" class=\"btn btn-primary\" disabled>\n          ➕ 新增记录\n        </button>\n      </div>\n    </header>\n\n    <!-- 数据表格容器 -->\n    <div id=\"table-container\">\n      <div id=\"table-placeholder\" class=\"placeholder-message\">\n        👈 请从左侧选择一个模型开始管理数据\n      </div>\n    </div>\n\n    <!-- 分页控件 -->\n    <footer id=\"pagination\" style=\"display: none;\">\n      <button id=\"prev-page\" class=\"btn btn-page\" disabled>上一页</button>\n      <span id=\"page-info\"></span>\n      <button id=\"next-page\" class=\"btn btn-page\" disabled>下一页</button>\n    </footer>\n  </main>\n\n  <!-- 编辑/创建模态框 -->\n  <div id=\"modal-overlay\" class=\"modal-overlay\" style=\"display: none;\">\n    <div class=\"modal\">\n      <div class=\"modal-header\">\n        <h2 id=\"modal-title\">编辑记录</h2>\n        <button id=\"modal-close\" class=\"btn-close\">✕</button>\n      </div>\n      <div class=\"modal-body\">\n        <form id=\"record-form\">\n          <div id=\"form-fields\"></div>\n        </form>\n      </div>\n      <div class=\"modal-footer\">\n        <button id=\"modal-cancel\" class=\"btn btn-secondary\">取消</button>\n        <button id=\"modal-submit\" class=\"btn btn-primary\">保存</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 删除确认模态框 -->\n  <div id=\"confirm-overlay\" class=\"modal-overlay\" style=\"display: none;\">\n    <div class=\"modal modal-sm\">\n      <div class=\"modal-header\">\n        <h2 id=\"confirm-title\">确认删除</h2>\n        <button id=\"confirm-close\" class=\"btn-close\">✕</button>\n      </div>\n      <div class=\"modal-body\">\n        <p id=\"confirm-message\">确定要删除这条记录吗？此操作不可撤销。</p>\n        <p id=\"confirm-detail\" class=\"confirm-detail\"></p>\n      </div>\n      <div class=\"modal-footer\">\n        <button id=\"confirm-cancel\" class=\"btn btn-secondary\">取消</button>\n        <button id=\"confirm-delete\" class=\"btn btn-danger\">删除</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast 通知 -->\n  <div id=\"toast\" class=\"toast\" style=\"display: none;\"></div>\n\n  <script>\n(function () {\n  var seq = 0;\n  var pending = {};\n  window.addEventListener('message', function (event) {\n    var data = event.data;\n    if (!data || data.__nyx !== 'res' || !pending[data.id]) return;\n    var waiter = pending[data.id];\n    delete pending[data.id];\n    if (data.ok) waiter.resolve(data.data);\n    else waiter.reject(new Error(data.error || '请求失败'));\n  });\n  function rpc(action, payload) {\n    return new Promise(function (resolve, reject) {\n      var id = ++seq;\n      pending[id] = { resolve: resolve, reject: reject };\n      parent.postMessage(Object.assign({ __nyx: 'req', id: id, action: action }, payload), '*');\n    });\n  }\n  window.AstrBotPluginPage = {\n    ready: function () { return Promise.resolve(); },\n    getI18n: function () { return {}; },\n    onContext: function () { return function () {}; },\n    t: function (key, fallback) { return fallback === undefined ? key : fallback; },\n    apiGet: function (endpoint, params) { return rpc('api:get', { endpoint: endpoint, params: params || {} }); },\n    apiPost: function (endpoint, body) { return rpc('api:post', { endpoint: endpoint, body: body || {} }); }\n  };\n})();\n</script>\n<script type=\"module\">\n/* ============================================================================\n   NyxBot 数据管理中心 — 核心逻辑\n   通过 AstrBot Plugin Pages Bridge 与后端 CRUD API 交互\n   支持中英文国际化（自主加载 i18n JSON，不依赖 bridge.t()）\n   ============================================================================ */\n\n// ----- 常量 -----\nconst PAGE_SIZE = 20;\nconst PAGE_PREFIX = \"pages.nyxbot-admin\";\n\n// ----- Bridge 引用 -----\nconst bridge = window.AstrBotPluginPage;\n\n// ----- 国际化（自主加载 JSON，确保语言切换后实时生效） -----\nlet i18nData = {};       // { \"zh-CN\": { ... }, \"en\": { ... } }\nlet currentLocale = \"zh-CN\";\n\n/** 将 Dashboard 传来的 locale（如 \"en-US\", \"zh-CN\", \"ru\"）标准化为 i18n 数据 key */\nfunction normalizeLocale(locale) {\n  if (!locale) return \"zh-CN\";\n  if (locale.startsWith(\"zh\")) return \"zh-CN\";\n  if (locale.startsWith(\"en\")) return \"en\";\n  if (locale.startsWith(\"ru\")) return \"ru\";\n  return \"zh-CN\";\n}\n\n/**\n * 获取当前 Page 的翻译文案，缺失时返回 fallback。\n * 使用自主加载的 i18n JSON，不依赖 bridge.t()（其 locale 编码在 JWT 中，切换后不更新）。\n */\nfunction t(key, fallback) {\n  const fullKey = `${PAGE_PREFIX}.${key}`;\n  // 1. 优先当前语言\n  const keys = fullKey.split(\".\");\n  let node = i18nData[currentLocale];\n  for (const k of keys) {\n    if (node == null) break;\n    node = node[k];\n  }\n  if (typeof node === \"string\") return node;\n  // 2. 回退到备用语言（zh-CN）\n  if (currentLocale !== \"zh-CN\") {\n    node = i18nData[\"zh-CN\"];\n    for (const k of keys) {\n      if (node == null) break;\n      node = node[k];\n    }\n    if (typeof node === \"string\") return node;\n  }\n  // 3. 回退到 en\n  if (currentLocale !== \"en\") {\n    node = i18nData[\"en\"];\n    for (const k of keys) {\n      if (node == null) break;\n      node = node[k];\n    }\n    if (typeof node === \"string\") return node;\n  }\n  // 4. 最终回退\n  return fallback !== undefined ? fallback : key;\n}\n\n/** 从 bridge.getI18n() 加载 i18n 数据（AstrBot 自动读取 .astrbot-plugin/i18n/*.json） */\nfunction loadI18n() {\n  i18nData = bridge.getI18n() || {};\n}\n\n// ----- 状态 -----\nlet currentModel = null;\nlet currentPage = 1;\nlet currentTotal = 0;\nlet modelCache = null;\nlet currentRows = [];\nlet pendingDeleteId = null;\nlet editingRecord = null;\n\n// ----- DOM 引用 -----\nconst $ = (sel) => document.querySelector(sel);\n\nconst modelList = $(\"#model-list\");\nconst modelFilter = $(\"#model-filter\");\nconst currentModelTitle = $(\"#current-model-title\");\nconst recordCount = $(\"#record-count\");\nconst syncBtn = $(\"#sync-btn\");\nconst createBtn = $(\"#create-btn\");\nconst tableContainer = $(\"#table-container\");\nconst pagination = $(\"#pagination\");\nconst prevPage = $(\"#prev-page\");\nconst nextPage = $(\"#next-page\");\nconst pageInfo = $(\"#page-info\");\nconst modalOverlay = $(\"#modal-overlay\");\nconst modalTitle = $(\"#modal-title\");\nconst formFields = $(\"#form-fields\");\nconst modalSubmit = $(\"#modal-submit\");\nconst confirmOverlay = $(\"#confirm-overlay\");\nconst confirmDetail = $(\"#confirm-detail\");\nconst confirmDeleteBtn = $(\"#confirm-delete\");\nconst toast = $(\"#toast\");\n\n// ----- 模型分类 → i18n key 映射 -----\nconst MODEL_CATEGORY_KEYS = {\n  \"alias\": \"basic\",\n  \"nodes\": \"basic\",\n  \"arbitration_tier\": \"basic\",\n  \"state_translation\": \"translation\",\n  \"night_wave\": \"game_content\",\n  \"relics\": \"game_content\",\n  \"relic_rewards\": \"game_content\",\n  \"sentinels\": \"game_content\",\n  \"upgrades\": \"game_content\",\n  \"warframes\": \"game_content\",\n  \"warframe_ability\": \"game_content\",\n  \"weapons\": \"game_content\",\n  \"reward_pool\": \"game_content\",\n  \"reward\": \"game_content\",\n  \"riven_tion\": \"riven\",\n  \"riven_tion_alias\": \"riven\",\n  \"riven_analyse_trend\": \"riven\",\n  \"riven_items\": \"riven\",\n  \"orders_items\": \"market\",\n  \"ephemeras\": \"market\",\n  \"lich_sister_weapons\": \"market\",\n  \"notification_history\": \"notification\",\n  \"mission_subscribe\": \"notification\",\n  \"mission_subscribe_user\": \"notification\",\n  \"mission_subscribe_user_check_type\": \"notification\",\n};\n\nfunction getCategoryKey(modelName) {\n  return MODEL_CATEGORY_KEYS[modelName] || \"other\";\n}\n\n// ============================================================================\n// 初始化\n// ============================================================================\nasync function init() {\n  try {\n    // 加载内联 i18n 数据（同步，无网络请求）\n    loadI18n();\n\n    const context = await bridge.ready();\n    console.log(\"NyxBot Admin: bridge ready\", context);\n\n    // 从 Dashboard 上下文初始化语言\n    currentLocale = normalizeLocale(context.locale);\n    applyLocale(currentLocale);\n\n    document.title = t(\"title\", \"NyxBot Data Manager\");\n    renderStaticTexts();\n\n    // 1. 通过 bridge.onContext 监听 Dashboard 语言切换（文档推荐方式）\n    bridge.onContext((ctx) => {\n      console.log(\"NyxBot Admin: onContext\", ctx.locale);\n      if (ctx.locale) {\n        currentLocale = normalizeLocale(ctx.locale);\n        applyLocale(ctx.locale);\n        // 自主 i18n，无需等待 bridge.t()，直接重渲染\n        renderStaticTexts();\n        if (modelCache) refreshModelList();\n        if (currentModel) {\n          refreshUITexts();\n          if (currentRows.length > 0) renderTable(currentRows);\n          else loadData();\n        }\n        if (modalOverlay.style.display === \"flex\") closeModal();\n      }\n    });\n\n    // 2. 通过 postMessage 兜底监听\n    window.addEventListener(\"message\", (event) => {\n      if (event.source !== window.parent) return;\n      const { type } = (event.data || {});\n      if (!type) return;\n\n      if (\n        (type === \"setTheme\" || type === \"themeChanged\" || type === \"changeTheme\")\n        && (event.data.theme === \"dark\" || event.data.theme === \"light\")\n      ) {\n        applyTheme(event.data.theme);\n      }\n      if (\n        (type === \"setLocale\" || type === \"localeChanged\" || type === \"changeLocale\")\n        && event.data.locale\n      ) {\n        currentLocale = normalizeLocale(event.data.locale);\n        applyLocale(event.data.locale);\n        renderStaticTexts();\n        if (modelCache) refreshModelList();\n        if (currentModel) {\n          refreshUITexts();\n          if (currentRows.length > 0) renderTable(currentRows);\n        }\n      }\n    });\n\n    // 3. 通过 CSS prefers-color-scheme 跟随系统主题\n    initSystemTheme();\n\n    await loadModelList();\n  } catch (err) {\n    console.error(\"初始化失败:\", err);\n    showToast(t(\"toast.init_failed\", \"Init failed\") + \": \" + err.message, \"error\");\n  }\n}\n\n/** 渲染页面中的静态文本（不随数据变化的部分） */\nfunction renderStaticTexts() {\n  // 侧边栏\n  const subtitle = document.querySelector(\".sidebar-subtitle\");\n  if (subtitle) subtitle.textContent = t(\"sidebar.subtitle\", \"Data Manager\");\n  modelFilter.placeholder = t(\"sidebar.filter_placeholder\", \"Filter models...\");\n\n  // 工具栏按钮\n  syncBtn.textContent = t(\"toolbar.sync\", \"🔄 Sync\");\n  syncBtn.title = t(\"toolbar.sync_title\", \"Sync from data source\");\n  createBtn.textContent = t(\"toolbar.create\", \"➕ New Record\");\n\n  // 分页按钮\n  prevPage.textContent = t(\"pagination.prev\", \"Previous\");\n  nextPage.textContent = t(\"pagination.next\", \"Next\");\n\n  // 确认对话框\n  $(\"#confirm-title\").textContent = t(\"confirm.title\", \"Confirm Delete\");\n  $(\"#confirm-message\").textContent = t(\"confirm.message\", \"Are you sure?\");\n  confirmDeleteBtn.textContent = t(\"confirm.delete_btn\", \"Delete\");\n  $(\"#confirm-cancel\").textContent = t(\"modal.cancel\", \"Cancel\");\n  $(\"#modal-cancel\").textContent = t(\"modal.cancel\", \"Cancel\");\n  modalSubmit.textContent = t(\"modal.save\", \"Save\");\n\n  // 模型列表（如果已缓存）\n  if (modelCache) refreshModelList();\n}\n\n/** 刷新动态 UI 文本（选择模型后） */\nfunction refreshUITexts() {\n  if (!currentModel) {\n    currentModelTitle.textContent = t(\"toolbar.select_model\", \"Select a model\");\n    return;\n  }\n  currentModelTitle.textContent = t(`models.${currentModel}`, currentModel);\n  recordCount.textContent = t(\"toolbar.records_count\", \"{n} records\").replace(\"{n}\", currentTotal);\n}\n\n// ============================================================================\n// Toast 通知\n// ============================================================================\nlet toastTimer = null;\n\nfunction showToast(message, type = \"info\") {\n  if (toastTimer) clearTimeout(toastTimer);\n  toast.textContent = message;\n  toast.className = `toast toast-${type}`;\n  toast.style.display = \"block\";\n  toastTimer = setTimeout(() => { toast.style.display = \"none\"; }, 3000);\n}\n\n// ============================================================================\n// 模型列表\n// ============================================================================\nasync function loadModelList() {\n  try {\n    const data = await bridge.apiGet(\"models\");\n    modelCache = data.models || [];\n    refreshModelList();\n  } catch (err) {\n    console.error(\"加载模型列表失败:\", err);\n    modelList.innerHTML = `<div class=\"loading-message\">${escapeHtml(err.message)}</div>`;\n  }\n}\n\nfunction refreshModelList() {\n  if (!modelCache) return;\n  const grouped = {};\n  for (const m of modelCache) {\n    const catKey = getCategoryKey(m.name);\n    if (!grouped[catKey]) grouped[catKey] = [];\n    grouped[catKey].push(m);\n  }\n  renderModelList(grouped);\n}\n\nfunction renderModelList(grouped) {\n  const filterText = modelFilter.value.toLowerCase().trim();\n  let html = \"\";\n\n  for (const [catKey, models] of Object.entries(grouped)) {\n    const filtered = filterText\n      ? models.filter(m => t(`models.${m.name}`, m.name).toLowerCase().includes(filterText) || m.name.toLowerCase().includes(filterText))\n      : models;\n\n    if (filtered.length === 0) continue;\n\n    const catLabel = t(`categories.${catKey}`, catKey);\n    html += `<div class=\"model-category\">${escapeHtml(catLabel)}</div>`;\n    for (const m of filtered) {\n      const isActive = currentModel === m.name;\n      const displayName = t(`models.${m.name}`, m.name);\n      html += `\n        <div class=\"model-item${isActive ? \" active\" : \"\"}\" data-model=\"${m.name}\">\n          <span class=\"model-name\">${escapeHtml(displayName)}</span>\n          ${m.has_sync ? '<span class=\"model-sync-badge\" title=\"sync\">↻</span>' : \"\"}\n        </div>`;\n    }\n  }\n\n  if (!html) {\n    html = `<div class=\"loading-message\">${t(\"sidebar.no_match\", \"No matching models\")}</div>`;\n  }\n\n  modelList.innerHTML = html;\n\n  modelList.querySelectorAll(\".model-item\").forEach(item => {\n    item.addEventListener(\"click\", () => selectModel(item.dataset.model));\n  });\n\n  // 更新静态文本（modelList 重新渲染后）\n  refreshUITexts();\n}\n\nmodelFilter.addEventListener(\"input\", () => {\n  if (modelCache) refreshModelList();\n});\n\nfunction selectModel(modelName) {\n  currentModel = modelName;\n  currentPage = 1;\n\n  currentModelTitle.textContent = t(`models.${modelName}`, modelName);\n  createBtn.disabled = false;\n\n  const modelMeta = (modelCache || []).find(m => m.name === modelName);\n  syncBtn.disabled = !modelMeta || !modelMeta.has_sync;\n  syncBtn.classList.remove(\"syncing\");\n\n  refreshModelList();\n  loadData();\n}\n\n// ============================================================================\n// 数据加载与表格渲染\n// ============================================================================\nasync function loadData() {\n  if (!currentModel) return;\n\n  tableContainer.innerHTML = `\n    <div class=\"placeholder-message\">\n      <span class=\"loading-spinner\"></span> ${t(\"table.loading\", \"Loading...\")}\n    </div>`;\n  pagination.style.display = \"none\";\n\n  try {\n    const params = { page: currentPage, size: PAGE_SIZE };\n    const data = await bridge.apiGet(`data/${currentModel}`, params);\n\n    currentTotal = data.total || 0;\n    recordCount.textContent = t(\"toolbar.records_count\", \"{n} records\").replace(\"{n}\", currentTotal);\n    renderTable(data.items || []);\n    renderPagination();\n  } catch (err) {\n    console.error(\"加载数据失败:\", err);\n    tableContainer.innerHTML = `\n      <div class=\"placeholder-message\" style=\"color: var(--danger);\">\n        ${t(\"table.load_failed\", \"Failed to load\")}: ${escapeHtml(err.message)}\n      </div>`;\n  }\n}\n\nfunction renderTable(items) {\n  currentRows = items;\n\n  if (items.length === 0) {\n    tableContainer.innerHTML = `<div class=\"placeholder-message\">${t(\"table.no_data\", \"No data\")}</div>`;\n    return;\n  }\n\n  const columns = Object.keys(items[0]);\n  const actionsLabel = t(\"table.actions\", \"Actions\");\n  const editLabel = t(\"modal.edit_btn\", \"Edit\");\n  const deleteLabel = t(\"modal.delete_btn\", \"Delete\");\n\n  let html = '<div class=\"table-wrapper\"><table><thead><tr>';\n  for (const col of columns) {\n    html += `<th>${escapeHtml(col)}</th>`;\n  }\n  html += `<th style=\"width: 100px;\">${escapeHtml(actionsLabel)}</th>`;\n  html += '</tr></thead><tbody>';\n\n  for (const row of items) {\n    html += `<tr data-row-id=\"${escapeHtml(String(row.id))}\">`;\n    for (const col of columns) {\n      const value = row[col];\n      if (value === null || value === undefined) {\n        html += '<td class=\"null-value\">—</td>';\n      } else {\n        html += `<td title=\"${escapeHtml(String(value))}\">${escapeHtml(String(value))}</td>`;\n      }\n    }\n    html += `\n      <td class=\"actions\">\n        <button class=\"btn-edit\" data-id=\"${escapeHtml(String(row.id))}\">${escapeHtml(editLabel)}</button>\n        <button class=\"btn-delete\" data-id=\"${escapeHtml(String(row.id))}\">${escapeHtml(deleteLabel)}</button>\n      </td>`;\n    html += '</tr>';\n  }\n\n  html += '</tbody></table></div>';\n  tableContainer.innerHTML = html;\n\n  tableContainer.querySelectorAll(\".btn-edit\").forEach(btn => {\n    btn.addEventListener(\"click\", () => openEditModal(btn.dataset.id));\n  });\n  tableContainer.querySelectorAll(\".btn-delete\").forEach(btn => {\n    btn.addEventListener(\"click\", () => openDeleteConfirm(btn.dataset.id));\n  });\n}\n\n// ============================================================================\n// 分页\n// ============================================================================\nprevPage.addEventListener(\"click\", () => {\n  if (currentPage > 1) { currentPage--; loadData(); }\n});\n\nnextPage.addEventListener(\"click\", () => {\n  const totalPages = Math.ceil(currentTotal / PAGE_SIZE) || 1;\n  if (currentPage < totalPages) { currentPage++; loadData(); }\n});\n\nfunction goToPage(page) {\n  const totalPages = Math.ceil(currentTotal / PAGE_SIZE) || 1;\n  if (page < 1 || page > totalPages || page === currentPage) return;\n  currentPage = page;\n  loadData();\n}\n\nfunction renderPagination() {\n  const totalPages = Math.ceil(currentTotal / PAGE_SIZE) || 1;\n\n  if (totalPages <= 1) {\n    pagination.style.display = \"none\";\n    return;\n  }\n\n  pagination.style.display = \"flex\";\n  prevPage.disabled = currentPage <= 1;\n  nextPage.disabled = currentPage >= totalPages;\n\n  const range = 3;\n  let start = Math.max(1, currentPage - range);\n  let end = Math.min(totalPages, currentPage + range);\n\n  while (end - start < range * 2 && (start > 1 || end < totalPages)) {\n    if (start > 1) start--;\n    else if (end < totalPages) end++;\n    else break;\n  }\n\n  let html = \"\";\n  if (start > 1) {\n    html += `<button class=\"btn btn-page\" data-page=\"1\">1</button>`;\n    if (start > 2) html += `<span class=\"page-ellipsis\">…</span>`;\n  }\n  for (let p = start; p <= end; p++) {\n    html += `<button class=\"btn btn-page${p === currentPage ? \" active\" : \"\"}\" data-page=\"${p}\">${p}</button>`;\n  }\n  if (end < totalPages) {\n    if (end < totalPages - 1) html += `<span class=\"page-ellipsis\">…</span>`;\n    html += `<button class=\"btn btn-page\" data-page=\"${totalPages}\">${totalPages}</button>`;\n  }\n\n  pageInfo.innerHTML = html;\n  pageInfo.querySelectorAll(\"button[data-page]\").forEach(btn => {\n    btn.addEventListener(\"click\", () => goToPage(parseInt(btn.dataset.page)));\n  });\n}\n\n// ============================================================================\n// 创建 / 编辑 模态框\n// ============================================================================\ncreateBtn.addEventListener(\"click\", () => {\n  editingRecord = null;\n  openFormModal(null);\n});\n\nfunction openEditModal(recordId) {\n  editingRecord = recordId;\n  openFormModal(recordId);\n}\n\nasync function openFormModal(recordId) {\n  modalTitle.textContent = recordId\n    ? t(\"modal.edit_record\", \"Edit Record\")\n    : t(\"modal.new_record\", \"New Record\");\n  formFields.innerHTML = `<div style=\"text-align:center;padding:20px;\"><span class=\"loading-spinner\"></span> ${t(\"modal.load_form\", \"Loading form...\")}</div>`;\n  modalOverlay.style.display = \"flex\";\n\n  try {\n    if (recordId) {\n      const record = currentRows.find(item => String(item.id) === String(recordId));\n      if (record) {\n        renderForm(record);\n      } else {\n        formFields.innerHTML = `<div style=\"text-align:center;padding:20px;color:var(--text-muted);\">${t(\"modal.record_not_in_cache\", \"Record not found\")}</div>`;\n      }\n    } else {\n      renderForm(null);\n    }\n  } catch (err) {\n    formFields.innerHTML = `<div style=\"color:var(--danger);text-align:center;padding:20px;\">${escapeHtml(err.message)}</div>`;\n  }\n}\n\nfunction renderForm(record) {\n  let fields = [];\n  const ths = tableContainer.querySelectorAll(\"thead th\");\n  if (ths.length > 0) {\n    ths.forEach(th => {\n      const text = th.textContent.trim();\n      const actionsLabel = t(\"table.actions\", \"Actions\");\n      if (text !== actionsLabel) fields.push(text);\n    });\n  }\n  if (fields.length === 0 && record) fields = Object.keys(record);\n  if (fields.length === 0 && currentRows.length > 0) fields = Object.keys(currentRows[0]);\n\n  if (fields.length === 0) {\n    formFields.innerHTML = `<div style=\"text-align:center;padding:20px;color:var(--text-muted);\">${t(\"modal.cannot_determine_fields\", \"Cannot determine fields\")}</div>`;\n    return;\n  }\n\n  let html = \"\";\n  for (const field of fields) {\n    const value = record ? (record[field] ?? \"\") : \"\";\n    // 使用 i18n 翻译标签，缺失时回退到原始字段名\n    const label = t(`fields.${field}`, field);\n    // 使用 i18n 翻译输入提示，优先精确匹配 → 回退 default\n    const placeholder = t(`placeholders.${field}`, t(\"placeholders.default\", \"\"));\n    // ID 类字段设为只读（字段名为 \"id\" 或 \"ids\"）\n    const isIdField = field === \"id\" || field === \"ids\";\n    html += `\n      <div class=\"form-group\">\n        <label for=\"field-${field}\">${escapeHtml(label)}</label>\n        <input\n          type=\"text\"\n          id=\"field-${field}\"\n          name=\"${field}\"\n          value=\"${escapeHtml(String(value))}\"\n          placeholder=\"${escapeHtml(placeholder)}\"\n          ${isIdField ? \"readonly\" : \"\"}\n        />\n      </div>`;\n  }\n  formFields.innerHTML = html;\n}\n\nmodalSubmit.addEventListener(\"click\", async () => {\n  const inputs = formFields.querySelectorAll(\"input, textarea\");\n  const data = {};\n  let recordId = null;\n\n  for (const input of inputs) {\n    const name = input.name;\n    const value = input.value.trim();\n    // 通过原始字段名（非翻译后的 label）判断 ID 字段\n    if (name === \"id\" || name === \"ids\") {\n      recordId = value;\n    } else {\n      data[name] = value;\n    }\n  }\n\n  // 新建时若填写了 ID，一并提交\n  if (!editingRecord && recordId) {\n    data.id = recordId;\n  }\n\n  try {\n    if (editingRecord) {\n      const raw = await bridge.apiPost(`data/${currentModel}/update`, { id: editingRecord, ...data });\n      const result = unwrapResult(raw);\n      if (result.ok) {\n        showToast(t(\"toast.update_success\", \"Updated\"), \"success\");\n        closeModal();\n        loadData();\n      } else {\n        showToast(t(\"toast.update_failed\", \"Update failed\") + \": \" + (result.error || t(\"toast.unknown_error\", \"Unknown\")), \"error\");\n      }\n    } else {\n      const raw = await bridge.apiPost(`data/${currentModel}/create`, data);\n      const result = unwrapResult(raw);\n      if (result.ok) {\n        showToast(t(\"toast.create_success\", \"Created\"), \"success\");\n        closeModal();\n        loadData();\n      } else {\n        showToast(t(\"toast.create_failed\", \"Create failed\") + \": \" + (result.error || t(\"toast.unknown_error\", \"Unknown\")), \"error\");\n      }\n    }\n  } catch (err) {\n    showToast(t(\"toast.operation_failed\", \"Operation failed\") + \": \" + err.message, \"error\");\n  }\n});\n\nfunction closeModal() {\n  modalOverlay.style.display = \"none\";\n  editingRecord = null;\n}\n\n$(\"#modal-close\").addEventListener(\"click\", closeModal);\n$(\"#modal-cancel\").addEventListener(\"click\", closeModal);\nmodalOverlay.addEventListener(\"click\", (e) => {\n  if (e.target === modalOverlay) closeModal();\n});\n\n// ============================================================================\n// 删除确认\n// ============================================================================\nfunction openDeleteConfirm(recordId) {\n  pendingDeleteId = recordId;\n\n  const row = tableContainer.querySelector(`[data-id=\"${recordId}\"]`)?.closest(\"tr\");\n  if (row) {\n    const cells = row.querySelectorAll(\"td\");\n    const details = [];\n    const ths = tableContainer.querySelectorAll(\"thead th\");\n    cells.forEach((td, i) => {\n      const actionsLabel = t(\"table.actions\", \"Actions\");\n      if (i < ths.length - 1) {\n        const colName = ths[i]?.textContent?.trim() || `col${i}`;\n        details.push(`${colName}: ${td.textContent?.trim()}`);\n      }\n    });\n    confirmDetail.textContent = details.join(\" | \");\n  } else {\n    confirmDetail.textContent = `ID: ${recordId}`;\n  }\n\n  confirmOverlay.style.display = \"flex\";\n}\n\nconfirmDeleteBtn.addEventListener(\"click\", async () => {\n  if (!pendingDeleteId) return;\n\n  try {\n    const raw = await bridge.apiPost(`data/${currentModel}/delete`, { id: pendingDeleteId });\n    const result = unwrapResult(raw);\n    if (result.ok) {\n      showToast(t(\"toast.delete_success\", \"Deleted\"), \"success\");\n      closeConfirm();\n      loadData();\n    } else {\n      showToast(t(\"toast.delete_failed\", \"Delete failed\") + \": \" + (result.error || t(\"toast.unknown_error\", \"Unknown\")), \"error\");\n    }\n  } catch (err) {\n    showToast(t(\"toast.delete_failed\", \"Delete failed\") + \": \" + err.message, \"error\");\n  }\n});\n\nfunction closeConfirm() {\n  confirmOverlay.style.display = \"none\";\n  pendingDeleteId = null;\n}\n\n$(\"#confirm-close\").addEventListener(\"click\", closeConfirm);\n$(\"#confirm-cancel\").addEventListener(\"click\", closeConfirm);\nconfirmOverlay.addEventListener(\"click\", (e) => {\n  if (e.target === confirmOverlay) closeConfirm();\n});\n\n// ============================================================================\n// 数据同步\n// ============================================================================\nsyncBtn.addEventListener(\"click\", async () => {\n  if (!currentModel) return;\n\n  syncBtn.classList.add(\"syncing\");\n  syncBtn.disabled = true;\n  const modelLabel = t(`models.${currentModel}`, currentModel);\n  showToast(t(\"toolbar.syncing\", \"Syncing...\").replace(\"{model}\", modelLabel), \"info\");\n\n  try {\n    const raw = await bridge.apiPost(`data/${currentModel}/sync`);\n    const result = unwrapResult(raw);\n    if (result.ok) {\n      showToast(result.message || t(\"toolbar.sync_success\", \"Sync completed\").replace(\"{model}\", modelLabel), \"success\");\n      loadData();\n    } else {\n      showToast(t(\"toolbar.sync_failed\", \"Sync failed\") + \": \" + (result.error || t(\"toast.unknown_error\", \"Unknown\")), \"error\");\n    }\n  } catch (err) {\n    showToast(t(\"toolbar.sync_failed\", \"Sync failed\") + \": \" + err.message, \"error\");\n  } finally {\n    syncBtn.classList.remove(\"syncing\");\n    const modelMeta = (modelCache || []).find(m => m.name === currentModel);\n    syncBtn.disabled = !modelMeta || !modelMeta.has_sync;\n  }\n});\n\n// ============================================================================\n// 通用 API 结果提取\n// ============================================================================\nfunction unwrapResult(raw) {\n  if (!raw) return { ok: false, data: null, error: \"No response\" };\n  if (typeof raw.success === \"boolean\") {\n    return { ok: raw.success, data: raw.data || null, error: raw.error || null };\n  }\n  if (raw.data && typeof raw.data.success === \"boolean\") {\n    return { ok: raw.data.success, data: raw.data.data || null, error: raw.data.error || null };\n  }\n  console.warn(\"未知 API 返回格式:\", raw);\n  return { ok: true, data: raw, error: null };\n}\n\n// ============================================================================\n// 工具函数\n// ============================================================================\nfunction escapeHtml(str) {\n  const div = document.createElement(\"div\");\n  div.textContent = str;\n  return div.innerHTML;\n}\n\n// ============================================================================\n// 主题 & 语言同步\n// ============================================================================\n\n/**\n * 应用主题到 <html data-theme>\n */\nfunction applyTheme(theme) {\n  document.documentElement.setAttribute(\"data-theme\", theme || \"dark\");\n}\n\n/**\n * 应用语言到 <html lang>\n */\nfunction applyLocale(locale) {\n  document.documentElement.setAttribute(\"lang\", locale || \"zh-CN\");\n}\n\n/**\n * 通过 CSS prefers-color-scheme 媒体查询跟随系统主题。\n * iframe 的 origin 为 null（AstrBot 通过 blob: URL 加载），\n * 无法访问 parent 的 localStorage，因此使用系统主题作为替代方案。\n * Dashboard 主题通常也跟随系统设置。\n */\nfunction initSystemTheme() {\n  const mq = window.matchMedia(\"(prefers-color-scheme: dark)\");\n  applyTheme(mq.matches ? \"dark\" : \"light\");\n\n  // 监听系统主题变化\n  try {\n    mq.addEventListener(\"change\", (e) => {\n      applyTheme(e.matches ? \"dark\" : \"light\");\n    });\n  } catch {\n    // 旧浏览器兼容\n    mq.addListener((e) => {\n      applyTheme(e.matches ? \"dark\" : \"light\");\n    });\n  }\n}\n\n// ============================================================================\n// 键盘快捷键\n// ============================================================================\ndocument.addEventListener(\"keydown\", (e) => {\n  if (e.key === \"Escape\") {\n    if (modalOverlay.style.display === \"flex\") closeModal();\n    else if (confirmOverlay.style.display === \"flex\") closeConfirm();\n  }\n});\n\n// ============================================================================\n// 启动\n// ============================================================================\ninit();\n\n</script>\n</body>\n</html>\n", "studio": "<!doctype html>\n<html lang=\"zh-CN\" data-theme=\"dark\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>遗物查询 · 渲染样板</title>\n  <style>\n/* 遗物查询 · 渲染样板 —— 与 AstrBot 面板一致的暗色底 */\n\n:root {\n  --bg: #0f131c;\n  --panel: #161c28;\n  --panel-alt: #1d2432;\n  --border: #2a3346;\n  --text: #f1f4fa;\n  --muted: #98a2b8;\n  --dim: #6b7590;\n  --gold: #e6b450;\n  --blue: #5b8def;\n  --green: #43d08a;\n  --radius: 12px;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  min-height: 100vh;\n  background: var(--bg);\n  color: var(--text);\n  font: 14px/1.5 \"Microsoft YaHei\", \"PingFang SC\", system-ui, sans-serif;\n}\n\n.topbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 20px;\n  border-bottom: 1px solid var(--border);\n  background: var(--panel);\n}\n\n.brand { display: flex; align-items: center; gap: 10px; font-weight: 600; letter-spacing: .5px; }\n.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 10px var(--gold); }\n.status { color: var(--muted); font-size: 13px; }\n\nmain {\n  display: grid;\n  grid-template-columns: 320px minmax(420px, 1fr) 280px;\n  gap: 16px;\n  padding: 16px;\n  align-items: start;\n}\n\n.panel {\n  background: var(--panel);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px;\n}\n\n/* ---------------- 搜索 ---------------- */\n\n.search-row { display: flex; gap: 8px; }\n\ninput[type=\"search\"], select {\n  flex: 1;\n  background: var(--panel-alt);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  color: var(--text);\n  padding: 8px 10px;\n  font: inherit;\n  outline: none;\n}\ninput[type=\"search\"]:focus, select:focus { border-color: var(--blue); }\n\nbutton {\n  border: 1px solid var(--border);\n  background: var(--panel-alt);\n  color: var(--text);\n  border-radius: 8px;\n  padding: 8px 12px;\n  font: inherit;\n  cursor: pointer;\n  transition: background .15s, border-color .15s;\n}\nbutton:hover { border-color: var(--blue); }\nbutton.primary { background: var(--blue); border-color: var(--blue); color: #0b1220; font-weight: 600; }\nbutton.primary:hover { filter: brightness(1.08); }\nbutton.ghost { background: transparent; }\nbutton:disabled { opacity: .5; cursor: not-allowed; }\n\n.row-meta { margin: 10px 0 8px; color: var(--dim); font-size: 12px; }\n\n.results {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  max-height: calc(100vh - 300px);\n  overflow-y: auto;\n}\n\n.results li {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  border-radius: 8px;\n  cursor: pointer;\n  border: 1px solid transparent;\n}\n.results li:hover { background: var(--panel-alt); }\n.results li.active { background: rgba(91, 141, 239, .16); border-color: rgba(91, 141, 239, .45); }\n\n.results .name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.results .badge {\n  font-size: 11px;\n  color: var(--gold);\n  border: 1px solid rgba(230, 180, 80, .4);\n  border-radius: 999px;\n  padding: 1px 7px;\n}\n\n.search-actions { display: flex; gap: 8px; margin-top: 10px; }\n.search-actions button { flex: 1; padding: 6px 8px; font-size: 13px; }\n\n/* ---------------- 预览 ---------------- */\n\n.preview { min-height: 520px; display: flex; flex-direction: column; }\n.preview-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n.preview-head .actions { display: flex; gap: 8px; }\n#preview-meta { color: var(--dim); font-size: 12px; }\n\n.canvas {\n  flex: 1;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  background:\n    linear-gradient(45deg, #121722 25%, transparent 25%) -10px 0/20px 20px,\n    linear-gradient(-45deg, #121722 25%, transparent 25%) -10px 0/20px 20px,\n    #0c1018;\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  padding: 16px;\n  overflow: auto;\n}\n\n.canvas img { max-width: 100%; border-radius: 8px; box-shadow: 0 12px 32px rgba(0, 0, 0, .45); }\n.placeholder { color: var(--dim); padding: 60px 20px; text-align: center; }\n\n/* ---------------- 控制 ---------------- */\n\n.controls h3 { margin: 4px 0 10px; font-size: 13px; color: var(--muted); font-weight: 600; letter-spacing: .5px; }\n.controls h3:not(:first-child) { margin-top: 18px; }\n\n.field { display: block; margin-bottom: 12px; color: var(--muted); font-size: 13px; }\n.field b { color: var(--text); font-weight: 600; }\n.field input[type=\"range\"] { width: 100%; margin-top: 6px; accent-color: var(--blue); }\n.field input[type=\"text\"], .field select { width: 100%; margin-top: 6px; }\n.field input[type=\"text\"] {\n  padding: 8px 10px;\n  color: var(--text);\n  background: var(--panel-2, #121722);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  font: inherit;\n}\n.field input[type=\"text\"]:focus { border-color: var(--blue); outline: none; }\n.check { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; margin-bottom: 8px; }\n\n.blocks { display: grid; gap: 6px; }\n.blocks label { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border: 1px solid var(--border); border-radius: 8px; font-size: 13px; }\n.tip { color: var(--dim); font-size: 12px; line-height: 1.6; margin: 12px 0 0; }\n\n@media (max-width: 1180px) {\n  main { grid-template-columns: 1fr; }\n  .results { max-height: 240px; }\n}\n\n</style>\n</head>\n<body>\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <span class=\"dot\"></span>\n      遗物查询 · 渲染样板\n    </div>\n    <div class=\"status\" id=\"status\">加载中…</div>\n  </header>\n\n  <main>\n    <aside class=\"panel search\">\n      <div class=\"search-row\">\n        <input id=\"q\" type=\"search\" placeholder=\"遗物名，例如 中纪 / 后纪 H3\" autocomplete=\"off\" />\n        <button id=\"search\" class=\"primary\">查询</button>\n      </div>\n      <div class=\"row-meta\" id=\"result-meta\">—</div>\n      <ul id=\"results\" class=\"results\"></ul>\n      <div class=\"search-actions\">\n        <button id=\"select-all\" class=\"ghost\">全选</button>\n        <button id=\"select-none\" class=\"ghost\">清空</button>\n      </div>\n    </aside>\n\n    <section class=\"panel preview\">\n      <div class=\"preview-head\">\n        <span id=\"preview-meta\">尚未渲染</span>\n        <div class=\"actions\">\n          <button id=\"render\" class=\"primary\">重新渲染</button>\n          <button id=\"save\" class=\"ghost\">保存版式</button>\n          <button id=\"reset\" class=\"ghost\">恢复默认</button>\n          <button id=\"export\" class=\"ghost\">导出 JSON</button>\n        </div>\n      </div>\n      <div class=\"canvas\" id=\"canvas\">\n        <div class=\"placeholder\" id=\"placeholder\">左侧选择遗物，右侧调版式，预览会自动刷新</div>\n        <img id=\"shot\" alt=\"遗物卡预览\" hidden />\n      </div>\n    </section>\n\n    <aside class=\"panel controls\">\n      <h3>版式参数</h3>\n      <label class=\"field\">主题\n        <select id=\"theme\">\n          <option value=\"dark\">深色 dark</option>\n          <option value=\"light\">浅色 light</option>\n          <option value=\"custom\">自定义 custom</option>\n        </select>\n      </label>\n      <label class=\"field\">列数 <b id=\"columns-val\">3</b>\n        <input id=\"columns\" type=\"range\" min=\"2\" max=\"4\" step=\"1\" value=\"3\" />\n      </label>\n      <label class=\"field\">最多遗物 <b id=\"maxItems-val\">20</b>\n        <input id=\"maxItems\" type=\"range\" min=\"1\" max=\"40\" step=\"1\" value=\"20\" />\n      </label>\n      <label class=\"field\">每题奖励 <b id=\"rewardsPerCard-val\">6</b>\n        <input id=\"rewardsPerCard\" type=\"range\" min=\"1\" max=\"6\" step=\"1\" value=\"6\" />\n      </label>\n      <label class=\"field\">奖励名换行\n        <select id=\"rewardLines\">\n          <option value=\"1\" selected>1 行（超出省略）</option>\n          <option value=\"2\">2 行（换行显示）</option>\n        </select>\n      </label>\n      <label class=\"check\"><input id=\"showDucats\" type=\"checkbox\" checked /> 显示杜卡德</label>\n\n      <h3>看板娘</h3>\n      <label class=\"check\"><input id=\"standingEnabled\" type=\"checkbox\" checked /> 显示看板娘</label>\n      <label class=\"check\"><input id=\"standingSeasonal\" type=\"checkbox\" checked /> 跟随季节换装</label>\n      <label class=\"field\">尺寸\n        <select id=\"standingSize\">\n          <option value=\"sm\">小 sm（200×300）</option>\n          <option value=\"md\" selected>中 md（280×420）</option>\n          <option value=\"lg\">大 lg（360×540）</option>\n        </select>\n      </label>\n\n      <h3>署名</h3>\n      <label class=\"check\"><input id=\"footerEnabled\" type=\"checkbox\" checked /> 显示署名</label>\n      <label class=\"field\">文本\n        <input id=\"footerText\" type=\"text\" maxlength=\"120\" placeholder=\"Posted by: KingPrimes\" />\n      </label>\n\n      <h3>区块</h3>\n      <div id=\"blocks\" class=\"blocks\"></div>\n      <p class=\"tip\">区块顺序固定为 页头 → 信息条 → 网格 → 看板娘 → 页脚；后续工作台会支持拖拽排序。</p>\n\n      <details class=\"global\">\n        <summary>全局默认（其他卡片）</summary>\n        <label class=\"field\">署名文本\n          <input id=\"globalSignature\" type=\"text\" maxlength=\"120\" placeholder=\"Posted by: KingPrimes\" />\n        </label>\n        <label class=\"check\"><input id=\"globalSignatureEnabled\" type=\"checkbox\" checked /> 显示署名</label>\n        <label class=\"check\"><input id=\"globalStanding\" type=\"checkbox\" checked /> 显示看板娘</label>\n        <label class=\"check\"><input id=\"globalStandingSeasonal\" type=\"checkbox\" checked /> 跟随季节换装</label>\n        <button id=\"saveBranding\" class=\"ghost\">保存全局设置</button>\n        <p class=\"tip\">作用于尚未迁移到版式系统的卡片；遗物卡以上面的版式设置为准。</p>\n      </details>\n    </aside>\n  </main>\n\n  <script>\n(function () {\n  var seq = 0;\n  var pending = {};\n  window.addEventListener('message', function (event) {\n    var data = event.data;\n    if (!data || data.__nyx !== 'res' || !pending[data.id]) return;\n    var waiter = pending[data.id];\n    delete pending[data.id];\n    if (data.ok) waiter.resolve(data.data);\n    else waiter.reject(new Error(data.error || '请求失败'));\n  });\n  function rpc(action, payload) {\n    return new Promise(function (resolve, reject) {\n      var id = ++seq;\n      pending[id] = { resolve: resolve, reject: reject };\n      parent.postMessage(Object.assign({ __nyx: 'req', id: id, action: action }, payload), '*');\n    });\n  }\n  window.AstrBotPluginPage = {\n    ready: function () { return Promise.resolve(); },\n    getI18n: function () { return {}; },\n    onContext: function () { return function () {}; },\n    t: function (key, fallback) { return fallback === undefined ? key : fallback; },\n    apiGet: function (endpoint, params) { return rpc('api:get', { endpoint: endpoint, params: params || {} }); },\n    apiPost: function (endpoint, body) { return rpc('api:post', { endpoint: endpoint, body: body || {} }); }\n  };\n})();\n</script>\n<script>\n/* ============================================================================\n   遗物查询 · 渲染样板\n   查询（GET search）→ 选择 → 渲染（POST render）→ 调版式 → 保存（POST layout）\n   所有请求走 Plugin Page Bridge；直接打开页面时退回同源 fetch。\n   ============================================================================ */\n\n// 注意：bridge-sdk.js 由服务端注入在 app.js **之后**，模块加载时读不到，\n// 必须在真正发请求时再取（并等 DOMContentLoaded 之后再启动）。\nconst API = \"relic-studio\";\nconst getBridge = () => window.AstrBotPluginPage || window.AstrBotPluginView;\nconst BLOCK_LABELS = { header: \"页头\", chips: \"信息条\", grid: \"卡片网格\", standing: \"看板娘\", footer: \"页脚\" };\n\nconst state = {\n  items: [],\n  selected: new Set(),\n  layout: null,\n  theme: \"dark\",\n  renderToken: 0,\n  timer: null,\n};\n\nconst $ = (id) => document.getElementById(id);\nconst els = {\n  status: $(\"status\"),\n  q: $(\"q\"),\n  search: $(\"search\"),\n  resultMeta: $(\"result-meta\"),\n  results: $(\"results\"),\n  previewMeta: $(\"preview-meta\"),\n  shot: $(\"shot\"),\n  placeholder: $(\"placeholder\"),\n  theme: $(\"theme\"),\n  columns: $(\"columns\"),\n  maxItems: $(\"maxItems\"),\n  rewardsPerCard: $(\"rewardsPerCard\"),\n  rewardLines: $(\"rewardLines\"),\n  showDucats: $(\"showDucats\"),\n  standingEnabled: $(\"standingEnabled\"),\n  standingSeasonal: $(\"standingSeasonal\"),\n  standingSize: $(\"standingSize\"),\n  footerEnabled: $(\"footerEnabled\"),\n  footerText: $(\"footerText\"),\n  globalSignature: $(\"globalSignature\"),\n  globalSignatureEnabled: $(\"globalSignatureEnabled\"),\n  globalStanding: $(\"globalStanding\"),\n  globalStandingSeasonal: $(\"globalStandingSeasonal\"),\n  saveBranding: $(\"saveBranding\"),\n  blocks: $(\"blocks\"),\n};\n\n/* ------------------------------------------------------------------ 请求层 */\n\nasync function apiGet(endpoint, params) {\n  const bridge = getBridge();\n  if (bridge?.apiGet) return bridge.apiGet(`${API}/${endpoint}`, params);\n  const url = new URL(`/api/plugin/astrbot_plugin_nyxbot/${API}/${endpoint}`, location.origin);\n  Object.entries(params || {}).forEach(([k, v]) => url.searchParams.set(k, v));\n  const res = await fetch(url, { credentials: \"include\" });\n  if (!res.ok) throw new Error(res.status === 401 ? \"未授权：请从面板内打开本页（直链没有 bridge 会话）\" : `HTTP ${res.status}`);\n  return res.json();\n}\n\nasync function apiPost(endpoint, body) {\n  const bridge = getBridge();\n  if (bridge?.apiPost) return bridge.apiPost(`${API}/${endpoint}`, body);\n  const res = await fetch(`/api/plugin/astrbot_plugin_nyxbot/${API}/${endpoint}`, {\n    method: \"POST\",\n    credentials: \"include\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body || {}),\n  });\n  if (!res.ok) throw new Error(res.status === 401 ? \"未授权：请从面板内打开本页（直链没有 bridge 会话）\" : `HTTP ${res.status}`);\n  return res.json();\n}\n\nfunction setStatus(text) {\n  els.status.textContent = text;\n}\n\n/* ------------------------------------------------------------------ 查询 */\n\nfunction renderResults() {\n  els.results.innerHTML = \"\";\n  for (const relic of state.items) {\n    const li = document.createElement(\"li\");\n    li.className = state.selected.has(relic.uniqueName) ? \"active\" : \"\";\n    li.innerHTML = `<span class=\"name\">${escapeHtml(relic.name)}</span><span class=\"badge\">${relic.rareCount || 0} 稀有</span>`;\n    li.addEventListener(\"click\", () => toggle(relic.uniqueName));\n    els.results.appendChild(li);\n  }\n  const total = state.items.length;\n  els.resultMeta.textContent = total ? `命中 ${total} 个遗物 · 已选 ${state.selected.size}` : \"没有匹配的遗物\";\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? \"\").replace(/[&<>\"']/g, (ch) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[ch]);\n}\n\nasync function doSearch() {\n  const q = els.q.value.trim();\n  setStatus(`查询「${q || \"全部\"}」…`);\n  try {\n    const data = await apiGet(\"search\", { q, limit: 40 });\n    state.items = data.items || [];\n    // 保留仍然存在的选中项，其余丢弃\n    const alive = new Set(state.items.map((item) => item.uniqueName));\n    state.selected = new Set([...state.selected].filter((name) => alive.has(name)));\n    renderResults();\n    if (!state.selected.size && state.items.length) {\n      state.items.slice(0, 6).forEach((item) => state.selected.add(item.uniqueName));\n      renderResults();\n    }\n    setStatus(`查询完成 · ${state.items.length} 个遗物`);\n    scheduleRender();\n  } catch (err) {\n    setStatus(`查询失败：${err.message}`);\n  }\n}\n\nfunction toggle(uniqueName) {\n  if (state.selected.has(uniqueName)) state.selected.delete(uniqueName);\n  else state.selected.add(uniqueName);\n  renderResults();\n  scheduleRender();\n}\n\n/* ------------------------------------------------------------------ 版式 */\n\nfunction blockOf(type) {\n  return (state.layout?.blocks || []).find((block) => block.type === type);\n}\n\nfunction syncControlsFromLayout() {\n  const grid = blockOf(\"grid\")?.props || {};\n  els.columns.value = grid.columns ?? 3;\n  els.maxItems.value = grid.maxItems ?? 20;\n  els.rewardsPerCard.value = grid.rewardsPerCard ?? 6;\n  els.rewardLines.value = String(grid.rewardLines ?? 1);\n  els.showDucats.checked = grid.showDucats !== false;\n\n  const standing = blockOf(\"standing\")?.props || {};\n  els.standingEnabled.checked = standing.enabled !== false;\n  els.standingSeasonal.checked = standing.seasonal !== false;\n  els.standingSize.value = standing.size || \"md\";\n\n  const footer = blockOf(\"footer\")?.props || {};\n  els.footerEnabled.checked = footer.enabled !== false;\n  els.footerText.value = footer.text ?? \"\";\n\n  updateValueLabels();\n  renderBlockToggles();\n}\n\nfunction updateValueLabels() {\n  $(\"columns-val\").textContent = els.columns.value;\n  $(\"maxItems-val\").textContent = els.maxItems.value;\n  $(\"rewardsPerCard-val\").textContent = els.rewardsPerCard.value;\n}\n\nfunction renderBlockToggles() {\n  els.blocks.innerHTML = \"\";\n  const blocks = state.layout?.blocks || [];\n  const enabled = new Set(blocks.filter((block) => block.props?.enabled !== false).map((block) => block.type));\n  for (const [type, label] of Object.entries(BLOCK_LABELS)) {\n    const wrapper = document.createElement(\"label\");\n    wrapper.innerHTML = `<input type=\"checkbox\" ${enabled.has(type) ? \"checked\" : \"\"} /> ${label}`;\n    wrapper.querySelector(\"input\").addEventListener(\"change\", (event) => {\n      toggleBlock(type, event.target.checked);\n    });\n    els.blocks.appendChild(wrapper);\n  }\n}\n\n/** 按固定顺序重建 blocks；参数从控件读，块开关写进 props.enabled。 */\nfunction rebuildLayout() {\n  const defaults = state.defaults || { blocks: [] };\n  const previous = new Map((state.layout?.blocks || []).map((block) => [block.type, block]));\n  const order = defaults.blocks.map((block) => block.type);\n\n  const blocks = [];\n  for (const type of order) {\n    const existing = previous.get(type);\n    if (!existing) continue;\n    const next = { type, props: { ...existing.props } };\n    if (type === \"grid\") {\n      next.props.columns = Number(els.columns.value);\n      next.props.maxItems = Number(els.maxItems.value);\n      next.props.rewardsPerCard = Number(els.rewardsPerCard.value);\n      next.props.rewardLines = Number(els.rewardLines.value);\n      next.props.showDucats = els.showDucats.checked;\n    } else if (type === \"standing\") {\n      next.props.enabled = els.standingEnabled.checked;\n      next.props.seasonal = els.standingSeasonal.checked;\n      next.props.size = els.standingSize.value;\n    } else if (type === \"footer\") {\n      next.props.enabled = els.footerEnabled.checked;\n      next.props.text = els.footerText.value.trim();\n    }\n    blocks.push(next);\n  }\n  state.layout = { ...state.layout, version: 2, blocks };\n}\n\n/** 开关某个块：保留块本身（顺序不变），只切 props.enabled。 */\nfunction setBlockEnabled(type, on) {\n  if (!state.layout) return;\n  state.layout = {\n    ...state.layout,\n    blocks: (state.layout.blocks || []).map((block) =>\n      block.type === type ? { ...block, props: { ...block.props, enabled: on } } : block\n    ),\n  };\n  if (type === \"standing\") els.standingEnabled.checked = on;\n  if (type === \"footer\") els.footerEnabled.checked = on;\n  renderBlockToggles();\n}\n\nfunction toggleBlock(type, on) {\n  setBlockEnabled(type, on);\n  scheduleRender();\n}\n\n/* ------------------------------------------------------------------ 渲染 */\n\nfunction scheduleRender() {\n  clearTimeout(state.timer);\n  state.timer = setTimeout(doRender, 350); // 防抖：拖滑块时不要每个像素都打后端\n}\n\nasync function doRender() {\n  if (!state.selected.size) {\n    els.shot.hidden = true;\n    els.placeholder.hidden = false;\n    els.previewMeta.textContent = \"尚未渲染（未选择遗物）\";\n    return;\n  }\n  rebuildLayout();\n  const token = ++state.renderToken;\n  els.previewMeta.textContent = \"渲染中…\";\n\n  try {\n    const data = await apiPost(\"render\", {\n      uniqueNames: [...state.selected],\n      layout: state.layout,\n      theme: state.theme,\n    });\n    if (token !== state.renderToken) return; // 有更新的请求，丢弃旧结果\n    els.shot.src = data.image;\n    els.shot.hidden = false;\n    els.placeholder.hidden = true;\n    els.previewMeta.textContent = `${data.width}×${data.height} · ${data.count} 个遗物 · ${data.ms} ms · ${(data.bytes / 1024).toFixed(0)} KB`;\n    setStatus(\"渲染完成\");\n  } catch (err) {\n    els.previewMeta.textContent = `渲染失败：${err.message}`;\n    setStatus(`渲染失败：${err.message}`);\n  }\n}\n\n/* ------------------------------------------------------------------ 动作 */\n\nasync function loadLayout() {\n  const data = await apiGet(\"layout\");\n  state.layout = data.layout;\n  state.defaults = data.defaults;\n  syncControlsFromLayout();\n}\n\nasync function loadBranding() {\n  try {\n    const data = await apiGet(\"branding\");\n    const branding = data.branding || {};\n    const signature = branding.signature || {};\n    const standing = branding.standing || {};\n    els.globalSignature.value = signature.text || \"\";\n    els.globalSignatureEnabled.checked = signature.enabled !== false;\n    els.globalStanding.checked = standing.enabled !== false;\n    els.globalStandingSeasonal.checked = standing.seasonal !== false;\n    els.footerText.placeholder = signature.text || \"Posted by: KingPrimes\";\n  } catch (err) {\n    // 全局设置读不到不影响版式编辑，留空即可\n    els.footerText.placeholder = \"Posted by: KingPrimes\";\n  }\n}\n\nasync function saveBranding() {\n  try {\n    const data = await apiPost(\"branding\", {\n      branding: {\n        signature: {\n          text: els.globalSignature.value.trim(),\n          enabled: els.globalSignatureEnabled.checked,\n        },\n        standing: {\n          enabled: els.globalStanding.checked,\n          seasonal: els.globalStandingSeasonal.checked,\n        },\n      },\n    });\n    setStatus(`全局设置已保存 → ${data.path}`);\n    els.footerText.placeholder = data.branding?.signature?.text || \"Posted by: KingPrimes\";\n    scheduleRender();\n  } catch (err) {\n    setStatus(`全局设置保存失败：${err.message}`);\n  }\n}\n\nasync function saveLayout() {\n  rebuildLayout();\n  try {\n    const data = await apiPost(\"layout\", { layout: state.layout });\n    state.layout = data.layout;\n    syncControlsFromLayout();\n    setStatus(`版式已保存 → ${data.saved}`);\n  } catch (err) {\n    setStatus(`保存失败：${err.message}`);\n  }\n}\n\nasync function resetLayout() {\n  state.layout = JSON.parse(JSON.stringify(state.defaults));\n  syncControlsFromLayout();\n  setStatus(\"已恢复默认版式\");\n  scheduleRender();\n}\n\nfunction exportLayout() {\n  const blob = new Blob([JSON.stringify(state.layout, null, 2)], { type: \"application/json\" });\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url;\n  link.download = \"relic_layout.json\";\n  link.click();\n  URL.revokeObjectURL(url);\n}\n\n/* ------------------------------------------------------------------ 绑定 */\n\nfunction bind() {\n  els.search.addEventListener(\"click\", doSearch);\n  els.q.addEventListener(\"keydown\", (event) => {\n    if (event.key === \"Enter\") doSearch();\n  });\n\n  $(\"select-all\").addEventListener(\"click\", () => {\n    state.items.forEach((item) => state.selected.add(item.uniqueName));\n    renderResults();\n    scheduleRender();\n  });\n  $(\"select-none\").addEventListener(\"click\", () => {\n    state.selected.clear();\n    renderResults();\n    scheduleRender();\n  });\n\n  els.theme.addEventListener(\"change\", () => {\n    state.theme = els.theme.value;\n    scheduleRender();\n  });\n\n  for (const id of [\"columns\", \"maxItems\", \"rewardsPerCard\"]) {\n    els[id].addEventListener(\"input\", () => {\n      updateValueLabels();\n      scheduleRender();\n    });\n  }\n  els.showDucats.addEventListener(\"change\", scheduleRender);\n  els.rewardLines.addEventListener(\"change\", scheduleRender);\n\n  els.standingEnabled.addEventListener(\"change\", () => {\n    setBlockEnabled(\"standing\", els.standingEnabled.checked);\n    scheduleRender();\n  });\n  els.standingSeasonal.addEventListener(\"change\", scheduleRender);\n  els.standingSize.addEventListener(\"change\", scheduleRender);\n\n  els.footerEnabled.addEventListener(\"change\", () => {\n    setBlockEnabled(\"footer\", els.footerEnabled.checked);\n    scheduleRender();\n  });\n  els.footerText.addEventListener(\"input\", scheduleRender);\n  els.saveBranding.addEventListener(\"click\", saveBranding);\n\n  $(\"render\").addEventListener(\"click\", doRender);\n  $(\"save\").addEventListener(\"click\", saveLayout);\n  $(\"reset\").addEventListener(\"click\", resetLayout);\n  $(\"export\").addEventListener(\"click\", exportLayout);\n}\n\nasync function boot() {\n  bind();\n  try {\n    await loadLayout();\n    setStatus(\"版式已加载\");\n  } catch (err) {\n    setStatus(`版式加载失败：${err.message}`);\n  }\n  await loadBranding();\n  await doSearch();\n}\n\nif (document.readyState === \"loading\") {\n  document.addEventListener(\"DOMContentLoaded\", boot);\n} else {\n  boot();\n}\n\n</script>\n</body>\n</html>\n"};
